changeSet.sql:
UPDATE act a SET
    tin          = coalesce(a.tin, x.v),
    subject_type = coalesce(a.subject_type, 'LEGAL_ENTITY')
FROM (
    SELECT id, sampler_identifier_value AS v FROM act153 WHERE sampler_identifier_type = 'TIN'
    UNION ALL
    SELECT id, sampler_identifier_value FROM act154 WHERE sampler_identifier_type = 'TIN'
    UNION ALL
    SELECT id, sampler_identifier_value FROM act223 WHERE sampler_identifier_type = 'TIN'
) x
WHERE a.id = x.id;
UPDATE act153 SET sampler_identifier_type = NULL, sampler_identifier_value = NULL WHERE sampler_identifier_type = 'TIN';
UPDATE act154 SET sampler_identifier_type = NULL, sampler_identifier_value = NULL WHERE sampler_identifier_type = 'TIN';
UPDATE act223 SET sampler_identifier_type = NULL, sampler_identifier_value = NULL WHERE sampler_identifier_type = 'TIN';

UPDATE act SET subject_type = NULL
WHERE subject_type IS NOT NULL
  AND subject_type NOT IN ('LEGAL_ENTITY', 'GEOGRAPHIC_POINT', 'PHYSICAL_PERSON');
